"""Verify every generated byte over HTTP against the reviewed local manifest."""
import argparse
import concurrent.futures
import hashlib
import json
import pathlib
import urllib.parse
import urllib.request
from datetime import datetime, timezone

parser = argparse.ArgumentParser()
parser.add_argument('--base', required=True)
parser.add_argument('--bundle', required=True)
parser.add_argument('--output', required=True)
args = parser.parse_args()
bundle = pathlib.Path(args.bundle)
manifest_bytes = (bundle / 'review-manifest.json').read_bytes()
manifest = json.loads(manifest_bytes)
base = args.base.rstrip('/') + '/'

def verify(record):
    relative = record['path']
    if relative.startswith('/') or '..' in pathlib.PurePosixPath(relative).parts:
        raise ValueError('Unsafe manifest resource: ' + relative)
    expected = record['sha256']
    local = (bundle / relative).read_bytes()
    if hashlib.sha256(local).hexdigest() != expected:
        raise AssertionError('Local bundle no longer matches manifest: ' + relative)
    request = urllib.request.Request(urllib.parse.urljoin(base, urllib.parse.quote(relative)), headers={'Cache-Control': 'no-cache'})
    with urllib.request.urlopen(request, timeout=45) as response:
        data = response.read()
        actual = hashlib.sha256(data).hexdigest()
        if response.status != 200 or actual != expected:
            raise AssertionError(f'Hosted resource mismatch: {relative} HTTP {response.status} {actual} != {expected}')
        return {'path': relative, 'status': response.status, 'bytes': len(data), 'sha256': actual}

records = list(manifest['files'])
# Older review manifests record the envelope separately; avoid duplicate checks.
for name, field in [('review-config.js', 'configSha256'), ('review-runtime.js', 'runtimeSha256')]:
    if not any(record['path'] == name for record in records):
        records.append({'path': name, 'sha256': manifest[field]})
records.append({'path': 'review-manifest.json', 'sha256': hashlib.sha256(manifest_bytes).hexdigest()})
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool:
    results = list(pool.map(verify, records))
report = {'base': base, 'checkedAt': datetime.now(timezone.utc).isoformat(), 'sourceSha': manifest['sourceSha'],
          'realBackend': manifest['realBackend'], 'manifestSha256': hashlib.sha256(manifest_bytes).hexdigest(),
          'resources': sorted(results, key=lambda record: record['path']), 'result': 'PASS'}
output = pathlib.Path(args.output)
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(report, indent=2) + '\n')
print(f"GLOBAL_HTTP_PASS {len(results)} resources, source {manifest['sourceSha']}, {base}")
